-- Migration 022: Request tracing and audit improvements\nALTER TABLE audit_logs ADD COLUMN request_id VARCHAR(36) NULL;\nCREATE INDEX idx_audit_request_id ON audit_logs(request_id);\n\n-- Migration 023: Performance indexes\nCREATE INDEX idx_predictions_user_jornada ON predictions(user_id, jornada_id);\nCREATE INDEX idx_proposals_group_jornada ON proposals(group_id, jornada_id);\nCREATE INDEX idx_rankings_score ON rankings(total_score DESC);\nCREATE INDEX idx_jornadas_status ON jornadas(status);\nCREATE INDEX idx_challenges_status ON challenges(status);\nCREATE INDEX idx_challenges_users ON challenges(challenger_id, challenged_id);\nCREATE INDEX idx_user_badges_user ON user_badges(user_id);\nCREATE INDEX idx_notifications_user_read ON notifications(user_id, is_read);\n\n-- Migration 024: Scraper source tracking\nCREATE TABLE scraper_logs (\n  id INT AUTO_INCREMENT PRIMARY KEY,\n  jornada_id INT NOT NULL,\n  source ENUM('resultados-futbol','football-data-api','manual') NOT NULL,\n  success BOOLEAN NOT NULL DEFAULT FALSE,\n  error_message TEXT NULL,\n  matches_updated INT DEFAULT 0,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (jornada_id) REFERENCES jornadas(id)\n);\nCREATE INDEX idx_scraper_logs_jornada ON scraper_logs(jornada_id);\n\n-- Migration 025: Challenge completion fields\nALTER TABLE challenges ADD COLUMN expired_at TIMESTAMP NULL;\nALTER TABLE challenges ADD COLUMN completed_at TIMESTAMP NULL;